-- #987 wave 1 (pure additions): Azshara creature abilities, imported from DeltaTho PR 15 file 2026_10_24_23_world.sql.
-- 81 creatures, 178 smart_scripts rows. Only creatures that have NO source_type 0 rows today are written here;
-- scripts that would replace existing rows are wave 2. Filters/fixes: see (not shipped)
-- Idempotent: DELETE of the listed entries then INSERT. AIName is set to SmartAI only where AIName and ScriptName are empty.
-- Undo: DELETE FROM smart_scripts WHERE source_type=0 AND FIND_IN_SET(entryorguid, <entries below>); and
--   UPDATE creature_template SET AIName='' WHERE FIND_IN_SET(entry, <entries below>); (entries that already had AIName SmartAI: see backup in (not shipped).

SET @ENTRIES := '830,6118,6190,6193,6194,6195,6196,6200,6201,6202,6350,6352,6370,6372,6375,6377,6646,6647,6648,6649,6650,6651,6652,7885,7886,8408,8660,8764,13896,35095,35096,35149,35177,35190,35198,35245,35312,35371,35466,35558,35584,35831,35832,35833,36012,36013,36015,36147,36304,36384,36385,36592,36593,36594,36611,36614,36636,36637,36639,36660,36680,36688,36752,36815,36816,36822,36849,36868,36884,36914,36925,36936,36975,36976,36989,37002,37740,37741,51508,51509,52018';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `AIName` = '' AND `ScriptName` = '' AND FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
